{
  "originalFormula": "J_{s} = A^{*}T^{2} \exp \left( -\\frac{\\phi_{b}}{kT} \\right)",
  "genericFormula": "J_{s} = A^{*}T^{2} \exp \\left( -\\frac{\\phi_{b}}{kT} \\right)",
  "description": "Esta fórmula representa a densidade de corrente de saturação em um semicondutor, que é a corrente que flui em um dispositivo quando ele está em equilíbrio térmico. A densidade de corrente é influenciada pela temperatura e pela energia de barreira do material.",
  "concepts": [
    "Densidade de corrente",
    "Temperatura",
    "Energia de barreira",
    "Constante de Boltzmann",
    "Efeito da temperatura na condutividade"
  ],
  "symbols": [
    {
      "symbol": "J_{s}",
      "description": "Representa a densidade de corrente de saturação, que é a quantidade de corrente elétrica por unidade de área em um semicondutor."
    },
    {
      "symbol": "A^{*}",
      "description": "É uma constante que depende das propriedades do material semicondutor e da estrutura do dispositivo, refletindo a eficiência de geração de portadores de carga."
    },
    {
      "symbol": "T",
      "description": "Representa a temperatura absoluta do sistema, medida em Kelvin, que afeta a energia térmica dos portadores de carga."
    },
    {
      "symbol": "\\phi_{b}",
      "description": "É a energia de barreira do material, que é a energia necessária para que os portadores de carga superem a barreira potencial e contribuam para a corrente."
    },
    {
      "symbol": "k",
      "description": "É a constante de Boltzmann, que relaciona a temperatura com a energia em sistemas físicos, desempenhando um papel fundamental na estatística térmica."
    },
    {
      "symbol": "\\exp",
      "description": "Representa a função exponencial, que é uma função matemática que descreve o crescimento ou decaimento exponencial, muito utilizada em processos térmicos e de transporte de carga."
    }
  ]
}
